package org.example.behavioral_pattern.observer_pattern.spring_boot;import org.springframework.context.event.EventListener;import org.springframework.stereotype.Component;@Componentpublic class OrderEmailNotifier {    @EventListener    public void handleOrderCreated(OrderCreatedEvent event) {        System.out.println("📧 Gửi email xác nhận đến: " + event.getOrder().getCustomerEmail());    }}